import { createInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice with expanded line items', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DES-DAY', qty: 5 },
    ],
  });
